/* 状态模拟：静态快照没有指针，把 chip 悬停的三条规则落在第二个 chip 上，声明与组件样式表一致。 */
.tab[data-dockkit-tab='tab-review'] { background: var(--dsw-alias-interactive-bg-hover); }
.tab[data-dockkit-tab='tab-review'] .tabClose { opacity: 1; pointer-events: auto; }
.tab[data-dockkit-tab='tab-review'] .tabTitle { mask-image: linear-gradient(to right, black calc(100% - 30px), transparent calc(100% - 14px)); }
